#version 300
uniform shader image;
uniform float2 size;
uniform float2 layer;
uniform float3x3 fromLayer;
uniform float3x3 toLayer;
uniform float4 screen;
uniform float time;
float2 amzCoord;
float4 amzOutput;
float2 amzScreenNorm() { float2 p=amzCoord-screen.xy; return float2(p.x/screen.z,1.0-p.y/screen.w); }
float2 amzLayerNorm() { float3 p=toLayer*float3(amzCoord,1.0); float2 n=p.xy/p.z/layer; return float2(n.x,1.0-n.y); }
float2 amzLayerCenter() { float3 p=fromLayer*float3(layer*.5,1.0); return p.xy/p.z-screen.xy; }
float4x4 amzRowMatrix(float3x3 m) { return float4x4(m[0].x,m[1].x,0.0,m[2].x, m[0].y,m[1].y,0.0,m[2].y, 0.0,0.0,1.0,0.0, m[0].z,m[1].z,0.0,m[2].z); }
float4x4 amzLayerToScreen() {
    float3x3 toNorm=float3x3(1.0/screen.z,0.0,0.0, 0.0,-1.0/screen.w,0.0,-screen.x/screen.z,1.0+screen.y/screen.w,1.0);
    float3x3 toPixels=float3x3(layer.x,0.0,0.0, 0.0,-layer.y,0.0, 0.0,layer.y,1.0);
    return amzRowMatrix(toNorm*fromLayer*toPixels);
}
float4x4 amzScreenToLayer() {
    float3x3 toPixels=float3x3(screen.z,0.0,0.0, 0.0,-screen.w,0.0, screen.x,screen.y+screen.w,1.0);
    float3x3 toNorm=float3x3(1.0/layer.x,0.0,0.0, 0.0,-1.0/layer.y,0.0,0.0,1.0,1.0);
    return amzRowMatrix(toNorm*toLayer*toPixels);
}
float2 getTexSize(float2 v) { return v; }
int amzIntMax(int a,int b) { return int(max(float(a),float(b))); }
int amzIntMin(int a,int b) { return int(min(float(a),float(b))); }
int amzIntAbs(int a) { return int(abs(float(a))); }
int amzIntClamp(int a,int b,int c) { return int(clamp(float(a),float(b),float(c))); }
uniform float2 amzVelocity,amzPivot,amzScale;
uniform float amzAngularVelocity,amzScaleVelocity,amzStartTime,amzEndTime;

struct AC_ImageInfo { int texture; float2 amzLocal_size; };
const float3x3 labPlaneInverse=float3x3(1);
float4x4 amzQuaternion(float4 q) {
    q /= max(length(q),0.000001);
    float x=q.x,y=q.y,z=q.z,w=q.w;
    return float4x4(1-2*(y*y+z*z),2*(x*y+w*z),2*(x*z-w*y),0,
                    2*(x*y-w*z),1-2*(x*x+z*z),2*(y*z+w*x),0,
                    2*(x*z+w*y),2*(y*z-w*x),1-2*(x*x+y*y),0,0,0,0,1);
}
const int amzPass=0;
uniform float amzIteration;
float4 amzSample_inputImg(float2 uv) { return float4(image.eval(((float2(uv.x,1.0-uv.y)*screen.zw+screen.xy)/1.0))); }
float4 amzTexture(int tex,float2 uv) { if(tex==0) return amzSample_inputImg(uv);return float4(0.0); }
float4 amzTexture(int tex,float2 uv,float bias){return amzTexture(tex,uv);}
uniform float2 amzp_start;
uniform float2 amzp_end;
uniform float amzp_evolution;
uniform float amzp_seed;
layout(color) uniform half4 amzp_color1;
layout(color) uniform half4 amzp_color2;
layout(color) uniform half4 amzp_color3;
uniform float amzp_limit;
uniform float amzp_intensity;
uniform float amzp_glow;
uniform float amzp_core;
uniform float amzp_alpha;
uniform float amzp_count;
uniform float amzp_octaves;
uniform float amzp_smooth;
uniform float amzp_blendMode;



        float sdLine( in float2 p, in float2 a, in float2 b )
        {
            float2 pa = p-a, ba = b-a;
            float h = clamp( dot(pa,ba)/dot(ba,ba), 0.0, 1.0 );
            return length( pa - ba*h );
        }

        float2 projectAndClamp(float2 a, float2 b) {
            return clamp(dot(a,b)/dot(b,b),0.0,1.0) * b;
        }


        float random (float2 st) {
            return fract(sin(dot(st.xy,
                                 float2(12.9898,78.233)))
                         * 43758.5453123);
        }



        float noise (float2 st) {
            float2 i = floor(st);
            float2 f = fract(st);


            float a = random(i);
            float b = random(i + float2(1.0, 0.0));
            float c = random(i + float2(0.0, 1.0));
            float d = random(i + float2(1.0, 1.0));


            float2 u;
            if((amzp_smooth>0.5)){


                u = smoothstep(0., 1., f);
            } else {

                u = f;
            }


            return mix(a, b, u.x) +
                    (c - a)* u.y * (1.0 - u.x) +
                    (d - b) * u.x * u.y;
        }










        float fractNoise (float2 st, int amzp_octaves) {
            st *= 4.;
            float result = noise(st);
            if ( amzp_octaves >= 2 )
                result += noise(st*2.)*0.5;
            if ( amzp_octaves >= 3 )
                result += noise(st*4.)*0.3;
            if ( amzp_octaves >= 4 )
                result += noise(st*8.)*0.2;
            if ( amzp_octaves >= 5 )
                result += noise(st*16.)*0.1;
            return result;
        }


        float2 l2s( float2 v, float4x4 acLTS ) {
            return (float4(v,0.,1.)*acLTS).xy;
        }

        float3 lightning( float2 st, float2 a, float2 b, float scale, float amzp_seed, float width, float amzp_limit ) {

            float2 ab = b - a;
            float2 n = normalize(ab).yx;
            n.y *= -1.;

            float2 p = projectAndClamp(st-a, ab)+a;
            float t = distance(p,a)/distance(b,a);
            float f = smoothstep(0.,0.5,0.5-abs(t-0.5));

            st += n*(fractNoise(float2(t,amzp_seed),int(amzp_octaves))-1.)* scale * 0.3 * length(ab)*f;


            float c = length(st - p);
            float l = smoothstep(clamp(amzp_limit,0.,0.5)-0.5, .5, abs(0.5-t));
            float xl = clamp(amzp_limit-0.5, 0., 1.);
            l = l * (1. - xl) + xl;
            return float3(smoothstep(0.006*width*amzp_core,0.,c),smoothstep(0.034*width,-0.032,c),smoothstep(0.034*width*amzp_glow,0.,c)) * l;
        }


        void amzRender() {
            float4 texColor = amzTexture(0,amzScreenNorm());
            float2 st = amzLayerNorm();
            st -= 0.5;
            st.x *= layer.x/layer.y;

            float3 lcolor = float3(0.);

            float adjseed = mod(258.35 + 42.78*amzp_seed,138.971);
            float w = 0.1;
            float slimit = 0.2;

            float2 a = amzp_start / 1000.;
            float2 b = amzp_end / 1000.;

            a.y *= -1.;
            b.y *= -1.;

            int icount = int(amzp_count);
            for( int i=0; i<icount; i++ ) {
                w += 0.2;
                slimit += 7.4;
                adjseed = mod(adjseed * sin(adjseed+1.2)+4.3,45.32);
                lcolor += lightning(st,a,b, 1., amzp_evolution+adjseed, pow((noise(float2(w,amzp_evolution))+1.)/2.,1.584), pow((noise(float2(slimit,amzp_evolution))*amzp_limit+1.)/2.584,1.584)) * amzp_intensity;
            }







            float4 color = ((amzp_color1 * lcolor.r) + (amzp_color2 * lcolor.g) + (amzp_color3 * lcolor.b)) / 3.;  

            color *= amzp_alpha;

            float4 result;
            if( int(amzp_blendMode)==0 ) {                
                color *= texColor.a;
                result = color + (texColor*(1.0-color.a));
            } else if( int(amzp_blendMode)==1 ) {         
                float4 c = color + float4(1.)*(1.-color.a);
                result = float4((texColor.rgb/texColor.a)*c.rgb,1.0) * texColor.a;
            } else if( int(amzp_blendMode)==2 ) {         
                result = float4( 1.-((1.-(texColor.rgb/texColor.a))*(1.-color.rgb)),1.0) * texColor.a;


            } else if( int(amzp_blendMode)==4 ) {         
                result = texColor * (1.0-color.a);
            } else if( int(amzp_blendMode)==6 ) {         
                result = color;
            } else if( int(amzp_blendMode)==5 ) {         
                float3 top = color.rgb / color.a;
                float3 bot = texColor.rgb / texColor.a;
                float3 t = smoothstep(0.5,0.5,bot);
                float3 r3 =
                        t * (1. - (1.-2.*(bot-0.5)) * (1.-top)) +
                        (1.-t) * ((2.*bot) * top);
                float4 r4 = float4(r3, 1.0) * color.a * texColor.a;
                result = texColor * (1.-r4.a) + r4;
            }

            amzOutput = result;

        }


half4 main(float2 coord) { amzCoord=coord*1.0; amzOutput=float4(0.0); amzRender(); return half4(amzOutput); }

